(window.__quranSurahs=window.__quranSurahs||{})[108]={"nomPhon":"Al-Kawthar","versets":{"1":{"text":"Nous t'avons certes, accordé l'Abondance.","arabe":"إِنَّآ أَعْطَيْنَٰكَ ٱلْكَوْثَرَ"},"2":{"text":"Accomplis la Salât pour ton Seigneur et sacrifie.","arabe":"فَصَلِّ لِرَبِّكَ وَٱنْحَرْ"},"3":{"text":"Celui qui te hait sera certes, sans postérité.","arabe":"إِنَّ شَانِئَكَ هُوَ ٱلْأَبْتَرُ"}}};